const LANGS = [{"code": "zh-cn", "name": "简体中文", "short": "简"}, {"code": "zh-tw", "name": "繁體中文", "short": "繁"}, {"code": "en", "name": "English", "short": "EN"}, {"code": "ja", "name": "日本語", "short": "日"}];

(function () {
  var $ = function (s, r) { return (r || document).querySelector(s); };
  var $$ = function (s, r) { return Array.prototype.slice.call((r || document).querySelectorAll(s)); };
  var prefix = document.body.getAttribute("data-prefix") || "";
  var storageKey = "ls-lang";
  var lang = "zh-cn";
  try { lang = localStorage.getItem(storageKey) || "zh-cn"; } catch (e) {}

  function t(key) {
    return (I18N[lang] && I18N[lang][key]) || I18N["zh-cn"][key] || key;
  }

  function applyLang(code) {
    if (!I18N[code]) code = "zh-cn";
    lang = code;
    try { localStorage.setItem(storageKey, lang); } catch (e) {}
    document.documentElement.lang = lang === "zh-cn" ? "zh-CN" : lang === "zh-tw" ? "zh-TW" : lang;
    $$("[data-i18n]").forEach(function (el) { el.textContent = t(el.getAttribute("data-i18n")); });
    $$("[data-i18n-ph]").forEach(function (el) { el.placeholder = t(el.getAttribute("data-i18n-ph")); });
    $$("[data-i18n-title]").forEach(function (el) { el.title = t(el.getAttribute("data-i18n-title")); });
    var active = null;
    LANGS.forEach(function (l) { if (l.code === lang) active = l; });
    $$(".ls-lang__code").forEach(function (el) { el.textContent = (active || LANGS[0]).short; });
    $$(".ls-lang__item").forEach(function (el) {
      var on = el.getAttribute("data-lang") === lang;
      el.classList.toggle("is-active", on);
      el.setAttribute("aria-checked", on ? "true" : "false");
    });
    var titleParts = document.title.split(" - ");
    if (titleParts.length === 2) document.title = (lang === "zh-cn" ? "" : "") + titleParts[0] + " - " + titleParts[1];
  }

  var toastTimer = null;
  function flash(msg) {
    var toast = $(".ls-toast");
    if (!toast) return;
    toast.textContent = msg;
    toast.classList.add("is-open");
    clearTimeout(toastTimer);
    toastTimer = setTimeout(function () { toast.classList.remove("is-open"); }, 2000);
  }

  /* grid filtering: search arrives as ?q= on the shop index */
  function initGrid() {
    var cols = $$(".ls-grid > .ls-col");
    var empty = $(".ls-item-message");
    if (!empty) return;
    var q = (new URLSearchParams(location.search).get("q") || "").trim().toLowerCase();
    if (q) {
      $$(".ls-chip").forEach(function (c) { c.classList.remove("is-primary"); });
      cols.forEach(function (col) {
        col.hidden = (col.getAttribute("data-name") || "").toLowerCase().indexOf(q) === -1;
      });
      var input = $(".ls-search__input");
      if (input) input.value = new URLSearchParams(location.search).get("q");
    }
    var visible = cols.filter(function (col) { return !col.hidden; }).length;
    empty.hidden = visible > 0;
  }

  document.addEventListener("click", function (e) {
    var langItem = e.target.closest(".ls-lang__item");
    if (langItem) {
      applyLang(langItem.getAttribute("data-lang"));
      $(".ls-lang__menu").classList.remove("is-open");
      return;
    }
    var langBtn = e.target.closest(".ls-lang__btn");
    if (langBtn) {
      var menu = $(".ls-lang__menu");
      var open = menu.classList.toggle("is-open");
      langBtn.setAttribute("aria-expanded", open ? "true" : "false");
      return;
    }
    if (!e.target.closest(".ls-lang")) {
      $(".ls-lang__menu").classList.remove("is-open");
      var btn = $(".ls-lang__btn");
      if (btn) btn.setAttribute("aria-expanded", "false");
    }

    var burger = e.target.closest(".ls-burger");
    if (burger) {
      var openMenu = $(".ls-collapse").classList.toggle("is-open");
      burger.classList.toggle("is-open", openMenu);
      burger.setAttribute("aria-expanded", openMenu ? "true" : "false");
      return;
    }

    var step = e.target.closest("[data-step]");
    if (step) {
      var input = $(".ls-qty__input");
      var next = (parseInt(input.value, 10) || 1) + parseInt(step.getAttribute("data-step"), 10);
      input.value = Math.max(1, next);
      return;
    }

    if (e.target.closest("[data-share]")) {
      var url = location.href;
      if (navigator.clipboard && navigator.clipboard.writeText) {
        navigator.clipboard.writeText(url).then(function () { flash("已复制链接"); }, function () { flash(url); });
      } else {
        flash(url);
      }
      return;
    }

    var nav = e.target.closest(".ls-nav__link");
    if (nav) {
      $(".ls-collapse").classList.remove("is-open");
      var b = $(".ls-burger");
      if (b) { b.classList.remove("is-open"); b.setAttribute("aria-expanded", "false"); }
    }

    var chip = e.target.closest(".ls-chip");
    if (chip) {
      var id = chip.getAttribute("data-id");
      var target = prefix + (Number(id) === 2 ? "" : "cat/" + id + "/");
      if (location.pathname.replace(/index\.html$/, "") === target) e.preventDefault();
    }
  });

  document.addEventListener("keydown", function (e) {
    if (e.key === "Enter" && e.target.classList && e.target.classList.contains("ls-search__input")) {
      e.preventDefault();
      var value = e.target.value.trim();
      if (!value) { flash(t("searchHint")); return; }
      location.href = prefix + "index.html?q=" + encodeURIComponent(value);
    }
    if (e.key === "Enter" && e.target.classList && e.target.classList.contains("ls-order-form__input")) {
      e.preventDefault();
      var form = e.target.closest("form");
      if (form) form.dispatchEvent(new Event("submit", { cancelable: true, bubbles: true }));
    }
  });

  document.addEventListener("submit", function (e) {
    var form = e.target;
    if (form.hasAttribute("data-buy")) {
      e.preventDefault();
      var contact = form.querySelector('[name="contact"]');
      if (contact && !contact.value.trim()) { contact.focus(); flash(t("contactPh")); return; }
      flash(t("buyNote"));
      return;
    }
    if (form.hasAttribute("data-query")) {
      e.preventDefault();
      var kw = form.querySelector('[name="keywords"]');
      var panel = $(".ls-no-result");
      if (!kw.value.trim()) { kw.focus(); flash(t("needInput")); return; }
      if (panel) panel.hidden = false;
      return;
    }
  });

  applyLang(lang);
  initGrid();
})();
